export class MpadsynthChannel extends MidiChannel {
    private _paramsDirty: bool = true;

    private _spread: f32 = <f32>(1);
    /** spread [init: 1, min: 0.02, max: 2.56, step: 0.02] · CC 0 */
    get spread(): f32 { return this._spread; }
    set spread(value: f32) { this._spread = value; this._paramsDirty = true; }
    private _tone: f32 = <f32>(1);
    /** tone [init: 1, min: 0.02, max: 2.56, step: 0.02] · CC 1 */
    get tone(): f32 { return this._tone; }
    set tone(value: f32) { this._tone = value; this._paramsDirty = true; }

    readonly effectDsp: MpadsynthEffectDsp = new MpadsynthEffectDsp();
    private efin: StaticArray<f32> = new StaticArray<f32>(2);
    private efout: StaticArray<f32> = new StaticArray<f32>(2);

    constructor(numvoices: i32, factoryFunc: (channel: MidiChannel, voiceindex: i32) => MidiVoice) {
        super(numvoices, factoryFunc);
        this.effectDsp.init(<i32>SAMPLERATE);
    }

    private applyParams(): void {
        for (let n = 0; n < this.voices.length; n++) {
            (this.voices[n] as Mpadsynth).applyParams();
        }
        this.effectDsp.fHslider0 = this._tone;
        this.effectDsp.control();
    }

    preprocess(): void {
        if (this._paramsDirty) {
            this._paramsDirty = false;
            this.applyParams();
        }
        this.efin[0] = this.signal.left;
        this.efin[1] = this.signal.right;
        this.effectDsp.frame(this.efin, this.efout);
        this.signal.left = this.efout[0];
        this.signal.right = this.efout[1];
    }

    controlchange(controller: u8, value: u8): void {
        super.controlchange(controller, value);
        switch (controller) {
            case 1:
                this.tone = 0.02 + (<f32>value / 127.0) * 2.54;
                break;
            case 0:
                this.spread = 0.02 + <f32>value / 127.0 * 2.54;
                break;
        }
    }
}

export function initializeMidiSynth(): void {
    midichannels[0] = new MpadsynthChannel(10, (channel: MidiChannel) => new Mpadsynth(channel));
    midichannels[0].controlchange(7, 100);
    midichannels[0].controlchange(10, 64);
    midichannels[0].controlchange(91, 10);

    // spread (CC 0, range: 0.02–2.56, default: 1)
    midichannels[0].controlchange(0, 49);
}

